parameters.jsCode:
const data = $input.first()?.json;
if (!data || !data.tg_id) {
  const chatId = $('Parse profile callback').item.json.chat_id;
  return [{
    json: {
      chat_id: chatId,
      text: "❌ Profile not found. Please restart the bot with /start",
      parse_mode: 'HTML',
      reply_markup: { inline_keyboard: [[{ text: '🔙 Back', callback_data: '/back' }]] }
    }
  }];
}

const chatId = data.tg_id;
const username = data.tg_username ? '@' + data.tg_username : 'Not set';
const firstName = data.tg_first_name || '—';
const lastName = data.tg_last_name || '';
const fullName = firstName + (lastName ? ' ' + lastName : '');
const premium = data.premium ? '✅ Yes' : '❌ No';
const language = data.language_code || 'en';
const registered = new Date(data.created_at).toLocaleDateString('en-GB');
const referralLink = data.referral_link || '';
const balance = Number(data.balance).toFixed(2);
const referrals = data.referrals_count || 0;

const musicMode = data.music_api_mode ? '🎵 PRO Mode (Deezer)' : '📼 TG Mode (Telegram)';
const botKicked = data.is_bot_kicked ? '⚠️ Blocked' : '✅ Active';

// Основные показатели (всегда показываем)
const totalSearches = data.total_searches || 0;
const totalTracks = data.total_tracks_received || 0;
const totalUploaded = data.total_uploaded_files || 0;
const totalDeezerDownloads = data.total_deezer_downloads || 0;
const totalPlaylists = data.total_playlists || 0;
const totalTracksInPlaylists = data.total_tracks_in_playlists || 0;
const totalShares = data.total_shares_sent || 0;

// Собираем строки activity (порядок важен)
let activityLines = [
  `• Searches: ${totalSearches}`,
  `• Tracks received: ${totalTracks}`,
  `• Uploaded files: ${totalUploaded}`,
  `• Deezer downloads: ${totalDeezerDownloads}`,
  `• Playlists created: ${totalPlaylists}`,
  `• Tracks in playlists: ${totalTracksInPlaylists}`
];
if (totalShares > 0) {
  activityLines.push(`• Shares sent: ${totalShares}`);
}
const activitySection = `\n\n📊 <b>Activity:</b>\n` + activityLines.join('\n');

// Топ артистов (только если есть)
let topArtistsSection = '';
if (data.top_artists && Array.isArray(data.top_artists) && data.top_artists.length > 0) {
  const artistsList = data.top_artists.map((a, i) => `${i+1}. ${a.artist} (${a.count} ${a.count === 1 ? 'track' : 'tracks'})`).join('\n');
  topArtistsSection = `\n\n🏆 <b>Top artists:</b>\n${artistsList}`;
}

// Реферальная ссылка
let referralSection = '';
if (referralLink) {
  referralSection = `\n\n🔗 <b>Your referral link:</b>\n${referralLink}`;
} else {
  referralSection = '\n\n🔗 <b>Your referral link:</b> not available';
}

const text = `👤 <b>Profile</b>

• Name: ${fullName}
• Username: ${username}
• Telegram Premium: ${premium}
• Language: ${language}
• Registered: ${registered}
• Search mode: ${musicMode}
• Bot status: ${botKicked}${activitySection}${topArtistsSection}

💰 <b>Balance:</b> ${balance} coins
👥 <b>Referrals:</b> ${referrals}${referralSection}

Share your link with friends!

@PocketSound_bot`;

return [{
  json: {
    chat_id: chatId,
    text: text,
    parse_mode: 'HTML',
    reply_markup: {
      inline_keyboard: [
        [{ text: '🔙 Back', callback_data: '/back' }],
        [{ text: '📂 My Playlists', callback_data: '/myplaylist' }]
      ]
    }
  }
}];

